/// The overlay (or "") and the language's table for a resolved locale.
pub(super) fn tables(locale: &str) -> (&'static str, &'static str) {
    let mut p = locale.split('-');
    let lang = p.next().unwrap_or("en");
    let rest: alloc::vec::Vec<&str> = p.collect();
    let script = rest.iter().find(|s| s.len() == 4).copied().unwrap_or("");
    let region = rest.iter().find(|s| s.len() == 2 || s.len() == 3).copied().unwrap_or("");
    let base = match lang {
        "de" => DE,
        "fr" => FR,
        "es" => ES,
        "it" => IT,
        "pt" => PT,
        "nl" => NL,
        "ja" => JA,
        "zh" => ZH,
        "ko" => KO,
        "ru" => RU,
        _ => EN,
    };
    let overlay = match (lang, script, region) {
        ("zh", "Hant", _) | ("zh", "", "TW" | "HK" | "MO") => ZH_HANT,
        ("es", _, "MX") => ES_MX,
        ("de", _, "AT") => DE_AT,
        ("pt", _, r) if !r.is_empty() && r != "BR" => PT_PT,
        ("en", _, r) if !r.is_empty() && !matches!(r, "US" | "AS" | "GU" | "MH" | "MP" | "PR" | "UM" | "VI") => EN_GB,
        ("es", _, r) if !r.is_empty() && !matches!(r, "ES" | "EA" | "IC" | "GQ" | "PH") => ES_419,
        ("fr", _, "CA") => FR_CA,
        _ => "",
    };
    (overlay, base)
}
